    const shipY = center.y + Math.sin(shipAngle) * orbitR;
    for (let a of asteroids) {
      const d = Math.hypot(a.x - shipX, a.y - shipY);
      if (d < a.r + shipR) {
        if (!collisionPlayed) {
          playTone(100, 0.3);
          collisionPlayed = true;
        }
        gameOver = true;
        break;
      }
    }
  }

